  border: 2px solid; border-radius: 5px; padding: 6px 11px 5px; background: var(--paper);
}
.stamp .cov { font-weight: 400; font-size: 11px; letter-spacing: .02em; opacity: .85; }
.stamp.pass { color: var(--pass); border-color: var(--pass); }
.stamp.fail { color: var(--fail); border-color: var(--fail); }
.stamp.lg { font-size: 14px; padding: 8px 14px 7px; }

/* --- views -------------------------------------------------------------- */
