  display: inline-flex; align-items: baseline; gap: 7px; background: var(--paper);
  border: 1px dashed var(--line); border-radius: 14px; padding: 5px 12px;
  font-family: var(--font-mono); font-size: 11.5px; color: var(--ink-2);
}
.chip b { color: var(--ink); font-weight: 600; }
.chip .basis { color: var(--ink-3); font-size: 10.5px; }

